import sys

def find_initial_cards(n, d, l):
    if n == 2:
        if abs(d) > l:
            return -1
        if d > 0:
            return [l, l - d]
        else:
            return [l + d, l]

    for x in range(1, l + 1):
        result = find_initial_cards(n - 1, x - d, l)
        if result != -1:
            return [x] + result
    return -1

def main():
    import sys
    input = sys.stdin.read().strip()
    n, d, l = map(int, input.split())
    result = find_initial_cards(n, d, l)
    if result == -1:
        print(-1)
    else:
        print(' '.join(map(str, result)))

main()
